CREATE TABLE `sys_region_bak_charsetfix_full_20260603` AS SELECT t.* FROM `sys_region` t JOIN `iboot_ref_utf8`.`sys_region` r ON t.`id` = r.`id` WHERE (t.`code` LIKE '%?%' AND r.`code` IS NOT NULL AND r.`code` NOT LIKE '%?%') OR (t.`name` LIKE '%?%' AND r.`name` IS NOT NULL AND r.`name` NOT LIKE '%?%') OR (t.`first_letter` LIKE '%?%' AND r.`first_letter` IS NOT NULL AND r.`first_letter` NOT LIKE '%?%');
UPDATE `sys_region` t JOIN `iboot_ref_utf8`.`sys_region` r ON t.`id` = r.`id` SET t.`code` = CASE WHEN t.`code` LIKE '%?%' AND r.`code` IS NOT NULL AND r.`code` NOT LIKE '%?%' THEN r.`code` ELSE t.`code` END, t.`name` = CASE WHEN t.`name` LIKE '%?%' AND r.`name` IS NOT NULL AND r.`name` NOT LIKE '%?%' THEN r.`name` ELSE t.`name` END, t.`first_letter` = CASE WHEN t.`first_letter` LIKE '%?%' AND r.`first_letter` IS NOT NULL AND r.`first_letter` NOT LIKE '%?%' THEN r.`first_letter` ELSE t.`first_letter` END WHERE (t.`code` LIKE '%?%' AND r.`code` IS NOT NULL AND r.`code` NOT LIKE '%?%') OR (t.`name` LIKE '%?%' AND r.`name` IS NOT NULL AND r.`name` NOT LIKE '%?%') OR (t.`first_letter` LIKE '%?%' AND r.`first_letter` IS NOT NULL AND r.`first_letter` NOT LIKE '%?%');
